import sys

M = 1_000_000_007


def fib(n, M=M):
    # fast doubling, iterative over bits from the top
    a, b = 0, 1
    for ch in bin(n)[2:]:
        c = a * (2 * b - a) % M
        d = (a * a + b * b) % M
        if ch == '1':
            a, b = d, (c + d) % M
        else:
            a, b = c, d
    return a


if __name__ == '__main__':
    print(fib(int(sys.argv[1])))
